<?php
declare(strict_types=1); require_once __DIR__ . '/../config/db.php'; require_once __DIR__ . '/../includes/layout.php'; requireAdmin(); if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf($_POST['csrf_token']??null);$id=filter_input(INPUT_POST,'ticket_id',FILTER_VALIDATE_INT);$status=$_POST['status']??'';if(!$id||!in_array($status,['open','in_progress','resolved'],true))redirectWith('maintenance.php','error','Invalid ticket update.');$stmt=$pdo->prepare('UPDATE maintenance_tickets SET status=:status WHERE id=:id');$stmt->execute([':status'=>$status,':id'=>$id]);redirectWith('maintenance.php','success','Ticket status updated.');}$tickets=$pdo->query('SELECT t.*,u.full_name,r.room_number FROM maintenance_tickets t JOIN users u ON u.id=t.tenant_id JOIN rooms r ON r.id=t.room_id ORDER BY t.created_at DESC')->fetchAll();pageHeader('Maintenance');?><div class="rounded-lg border border-slate-200 bg-white p-6 shadow-sm"><h1 class="text-2xl font-bold">Maintenance tickets</h1><div class="mt-5 space-y-4"><?php foreach($tickets as $ticket):?><div class="border-b pb-4"><div class="flex justify-between gap-4"><div><p class="font-semibold"><?=e($ticket['category'])?> · <?=e($ticket['room_number'])?></p><p class="text-sm text-slate-600"><?=e($ticket['full_name'])?>: <?=e($ticket['description'])?></p></div><?=badge($ticket['status'])?></div><form class="mt-3 flex gap-2" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="ticket_id" value="<?=e((string)$ticket['id'])?>"><select class="rounded border p-2" name="status"><option value="open">Open</option><option value="in_progress">In Progress</option><option value="resolved">Resolved</option></select><button class="rounded bg-slate-900 px-3 py-2 text-white">Update</button></form></div><?php endforeach;?></div></div><?php pageFooter();?>